package com.library.catalogpublication;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import org.springframework.dao.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.*;
import org.springframework.transaction.support.TransactionTemplate;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static com.library.catalogattributes.CatalogAttributeSupport.JSON;
import static com.library.catalogattributes.CatalogAttributeSupport.obj;
import static com.library.catalogattributes.CatalogAttributeSupport.tree;
import static com.library.catalogattributes.CatalogAttributeSupport.hash;
import static com.library.catalogattributes.CatalogAttributeSupport.write;
import static com.library.catalogattributes.CatalogAttributeSupport.read;
import static com.library.catalogattributes.CatalogAttributeSupport.bytes;
import static com.library.catalogattributes.CatalogAttributeSupport.num;
import static com.library.catalogattributes.CatalogAttributeSupport.now;
import static com.library.catalogattributes.CatalogAttributeSupport.local;
import static com.library.catalogattributes.CatalogAttributeSupport.time;
import static com.library.catalogattributes.CatalogAttributeSupport.insert;
import static com.library.catalogattributes.CatalogAttributeSupport.canonical;
import static com.library.catalogpublication.PublicationSupport.*;

@Service
public class PublicationService {
    private final JdbcTemplate jdbc;private final PlatformTransactionManager transactions;
    public PublicationService(JdbcTemplate j,PlatformTransactionManager t){jdbc=new PublicationJdbc(Objects.requireNonNull(j.getDataSource()));transactions=t;}
    private <T>T tx(boolean readOnly,Supplier<T> work){TransactionTemplate t=new TransactionTemplate(transactions);t.setIsolationLevel(readOnly?TransactionDefinition.ISOLATION_REPEATABLE_READ:TransactionDefinition.ISOLATION_READ_COMMITTED);t.setReadOnly(readOnly);t.setTimeout(15);try{return t.execute(s->work.get());}catch(Failure e){throw e;}catch(QueryTimeoutException|PessimisticLockingFailureException|TransactionTimedOutException e){throw failure(409,"CATALOG_BUSY");}catch(DataAccessException e){throw failure(500,"PUBLICATION_SAVE_FAILED");}}
    private ObjectNode current(long id,boolean lock){if(id<=0)invalid();ObjectNode n=PublicationHistory.snapshot(jdbc,id,lock);if(n==null||n.path("deleted").asLong()!=0)throw failure(404,"BOOK_NOT_FOUND").context(null,id);return n;}
    public JsonNode book(long id,Actor a){a.role();return tx(true,()->obj("schemaVersion",1,"book",PublicationHistory.publication(jdbc,current(id,false))));}
    private ObjectNode validate(JsonNode input,Actor a){a.role();keys(input,"operationKey,mode,reason,entries");key(input.get("operationKey"));word(input.get("mode"),List.of("MANUAL"));text(input.get("reason"),500,false,false);JsonNode entries=input.get("entries");if(!entries.isArray()||entries.isEmpty()||entries.size()>100)invalid();a.batch(entries.size());TreeMap<Long,JsonNode> sorted=new TreeMap<>();for(JsonNode e:entries){keys(e,"bookId,expectedRevision,expectedMetadataDigest,changes,evidence");long id=number(e.get("bookId"),true);if(sorted.put(id,e)!=null)invalid();number(e.get("expectedRevision"),false);digest(e.get("expectedMetadataDigest"));JsonNode changes=e.get("changes");keys(changes,"publishDate,pages,description");boolean operation=false;for(String f:FIELDS){JsonNode change=changes.get(f);if(change.isNull())continue;operation=true;String action=word(change.get("action"),List.of("SET","CLEAR"));if(action.equals("CLEAR")){keys(change,"action");continue;}keys(change,"action,value");JsonNode value=change.get("value");switch(f){case "publishDate"->date(value);case "pages"->{if(number(value,false)>99999)invalid();}case "description"->text(value,2000,true,true);default->invalid();}}if(!operation)invalid();JsonNode ev=e.get("evidence");keys(ev,"kind,reference");word(ev.get("kind"),List.of("COPYRIGHT_PAGE","PUBLISHER_MATERIAL","LEGACY_RECORD","MANUAL_REVIEW"));text(ev.get("reference"),1000,false,false);}ObjectNode n=input.deepCopy();n.set("entries",tree(sorted.values()));return (ObjectNode)canonical(n);}
    private String inputHash(JsonNode input,Actor a){return hash(obj("actorId",a.id(),"input",input));}
    private Map<String,Object> request(Long id,String key,boolean lock){var rows=jdbc.queryForList("SELECT * FROM catalog_publication_request WHERE "+(id==null?"operation_key=?":"id=?")+(lock?" FOR UPDATE":""),id==null?bytes(key):id);return rows.isEmpty()?null:rows.get(0);}
    private void owned(Map<String,Object> r,Actor a){a.role();if(r==null)throw failure(404,"REQUEST_NOT_FOUND");if(num(r.get("actor_id"))!=a.id())throw failure(403,"OWNER_REQUIRED");a.batch(read(PublicationHistory.string(r.get("request_json"))).path("entries").size());}
    private JsonNode view(Map<String,Object> r){return obj("requestId",num(r.get("id")),"operationKey",new String((byte[])r.get("operation_key"),java.nio.charset.StandardCharsets.UTF_8),"mode","MANUAL","state",r.get("state"),"previewDigest",r.get("preview_digest"),"expiresAt",time(r.get("expires_at")),"preview",read(PublicationHistory.string(r.get("preview_json"))),"receipt",r.get("receipt_json")==null?null:read(PublicationHistory.string(r.get("receipt_json"))));}
    public JsonNode getRequest(long id,Actor a){a.role();if(id<=0)invalid();return tx(true,()->{var r=request(id,null,false);owned(r,a);return view(r);});}
    public JsonNode getByKey(String k,Actor a){a.role();key(tree(k));return tx(true,()->{var r=request(null,k,false);owned(r,a);return view(r);});}
    private JsonNode duplicate(Map<String,Object> r,JsonNode input,Actor a){if(num(r.get("actor_id"))!=a.id()||!r.get("input_hash").equals(inputHash(input,a)))throw failure(409,"IDEMPOTENCY_KEY_REUSED");owned(r,a);return view(r);}
    private void expected(JsonNode e,JsonNode before){if(e.path("expectedRevision").asLong()!=before.path("revision").asLong()||!e.path("expectedMetadataDigest").asText().equals(hash(before)))throw changed().context(null,before.path("bookId").asLong());}
    private ObjectNode after(ObjectNode before,JsonNode entry){ObjectNode after=before.deepCopy();for(String f:FIELDS){JsonNode c=entry.path("changes").get(f);if(c.isNull())continue;after.set(f,c.path("action").asText().equals("CLEAR")?NullNode.instance:c.get("value"));}if(!PublicationHistory.fields(before,after).isEmpty()){if(before.path("revision").asLong()==Long.MAX_VALUE)throw changed();after.put("revision",before.path("revision").asLong()+1);}return after;}
    private ArrayNode previewBooks(JsonNode input){ArrayNode rows=JSON.createArrayNode();for(JsonNode e:input.path("entries")){long id=e.path("bookId").asLong();ObjectNode before=current(id,true);expected(e,before);ObjectNode after=after(before,e);ArrayNode fields=PublicationHistory.fields(before,after);rows.add(obj("bookId",id,"before",PublicationHistory.publication(jdbc,before),"after",PublicationHistory.publication(jdbc,after),"changes",e.get("changes"),"evidence",e.get("evidence"),"changedFields",fields,"willChange",!fields.isEmpty()));}return rows;}
    public JsonNode preview(JsonNode raw,Actor a){ObjectNode input=validate(raw,a);return tx(false,()->{PublicationHistory.lock(jdbc);String k=input.path("operationKey").asText();var existing=request(null,k,true);if(existing!=null)return duplicate(existing,input,a);String at=now(),expires=Instant.parse(at).plusSeconds(900).toString();ObjectNode preview=obj("schemaVersion",1,"mode","MANUAL","reason",input.get("reason"),"createdAt",at,"expiresAt",expires,"books",previewBooks(input));long id=insert(jdbc,"INSERT INTO catalog_publication_request(operation_key,actor_id,mode,input_hash,request_json,preview_json,preview_digest,state,created_at,expires_at) VALUES (?,?,'MANUAL',?,?,?,?,'PREVIEWED',?,?)",bytes(k),a.id(),inputHash(input,a),write(input),write(preview),hash(preview),local(at),local(expires));return view(request(id,null,false));});}
    public JsonNode confirm(long id,JsonNode input,Actor a){a.role();if(id<=0)invalid();keys(input,"operationKey,previewDigest");String k=key(input.get("operationKey")),digest=digest(input.get("previewDigest"));try{return tx(false,()->{PublicationHistory.lock(jdbc);var r=request(id,null,true);owned(r,a);if(!Arrays.equals(bytes(k),(byte[])r.get("operation_key"))||!digest.equals(r.get("preview_digest")))throw failure(409,"IDEMPOTENCY_KEY_REUSED");if(r.get("state").equals("COMMITTED"))return read(PublicationHistory.string(r.get("receipt_json")));if(!Instant.parse(time(r.get("expires_at"))).isAfter(Instant.now()))throw failure(409,"PREVIEW_EXPIRED");JsonNode request=read(PublicationHistory.string(r.get("request_json"))),preview=read(PublicationHistory.string(r.get("preview_json")));String at=now();ArrayNode receipts=JSON.createArrayNode();for(int i=0;i<request.path("entries").size();i++){JsonNode e=request.path("entries").get(i),frozen=preview.path("books").get(i);long book=e.path("bookId").asLong();ObjectNode before=PublicationHistory.snapshot(jdbc,book,true);if(before==null||before.path("deleted").asLong()!=0)throw changed().context(id,book);expected(e,before);ObjectNode after=after(before,e);if(!hash(after).equals(frozen.path("after").path("metadataDigest").asText()))throw changed().context(id,book);ArrayNode fields=PublicationHistory.fields(before,after);Long event=null;if(!fields.isEmpty()){if(jdbc.update("UPDATE book SET publish_date=?,pages=?,description=?,publication_revision=?,update_time=CURRENT_TIMESTAMP WHERE id=? AND publication_revision=? AND deleted=0",after.get("publishDate").isNull()?null:after.get("publishDate").textValue(),after.get("pages").isNull()?null:after.get("pages").intValue(),after.get("description").isNull()?null:after.get("description").textValue(),after.path("revision").asLong(),book,before.path("revision").asLong())!=1)throw changed().context(id,book);event=PublicationHistory.event(jdbc,id,book,"MANUAL",before,after,fields,e.get("evidence"),a.id(),request.path("reason").asText(),at);}receipts.add(obj("bookId",book,"changed",!fields.isEmpty(),"beforeRevision",before.get("revision"),"afterRevision",after.get("revision"),"eventId",event,"publication",PublicationHistory.publication(jdbc,after),"applied",e.get("changes"),"evidence",e.get("evidence")));}ObjectNode receipt=obj("schemaVersion",1,"requestId",id,"operationKey",k,"mode","MANUAL","actorId",a.id(),"confirmedAt",at,"books",receipts);if(jdbc.update("UPDATE catalog_publication_request SET state='COMMITTED',receipt_json=?,committed_at=? WHERE id=? AND state='PREVIEWED'",write(receipt),local(at),id)!=1)throw changed();return read(write(receipt));});}catch(Failure e){throw e.context(id,null);}}
    public JsonNode events(long id,int page,int size,Actor a){a.role();if(page<1||size<1||size>100)invalid();return tx(true,()->{if(id<=0)invalid();if(PublicationHistory.snapshot(jdbc,id,false)==null)throw failure(404,"BOOK_NOT_FOUND").context(null,id);long total=jdbc.queryForObject("SELECT COUNT(*) FROM catalog_publication_event WHERE book_id=? AND actor_id=?",Long.class,id,a.id());List<JsonNode> records=jdbc.query("SELECT * FROM catalog_publication_event WHERE book_id=? AND actor_id=? ORDER BY id DESC LIMIT ? OFFSET ?",(rs,row)->obj("eventId",rs.getLong("id"),"schemaVersion",1,"bookId",rs.getLong("book_id"),"requestId",rs.getObject("request_id"),"kind",rs.getString("kind"),"beforeRevision",rs.getLong("before_revision"),"afterRevision",rs.getLong("after_revision"),"changedFields",read(rs.getString("changed_fields_json")),"before",read(rs.getString("before_json")),"after",read(rs.getString("after_json")),"evidence",rs.getString("evidence_json")==null?null:read(rs.getString("evidence_json")),"actorId",a.id(),"occurredAt",time(rs.getTimestamp("occurred_at")),"reason",rs.getString("reason")),id,a.id(),size,(long)(page-1)*size);return obj("records",records,"total",total,"page",page,"size",size,"pages",(total+size-1)/size);});}
}
